WITH cleaned AS (SELECT id, order_id, product_id, COALESCE(quantity, 0) AS quantity_filled FROM order_items WHERE product_id IN (3, 4, 37)), deduped AS (SELECT id, order_id, product_id, quantity_filled FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity_filled NULLS LAST, id) AS dedup_rank FROM cleaned) t WHERE dedup_rank = 1), ranked AS (SELECT * FROM deduped QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY quantity_filled DESC, id) = 1), ranked_order_items AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY quantity_filled DESC NULLS FIRST, id) AS rn FROM ranked QUALIFY rn = 1), with_dims AS (SELECT e.*, b.channel, b.discount FROM ranked_order_items e LEFT JOIN orders b ON e.order_id = b.id), with_windows AS (SELECT id, product_id, channel, discount, FIRST_VALUE(discount) IGNORE NULLS OVER w_hist AS first_known_discount, AVG(quantity_filled) OVER (PARTITION BY channel ORDER BY quantity_filled, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS quantity_filled_avg_2 FROM with_dims WHERE channel = 'web' WINDOW w_hist AS (PARTITION BY order_id ORDER BY rn, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT s.id, s.product_id, s.channel, s.first_known_discount, s.quantity_filled_avg_2, CASE WHEN channel RLIKE '^(store|mobile)$' THEN 'GROUP_B' WHEN channel RLIKE '^(web|partner)$' THEN 'OTHER_ZONE' ELSE 'GROUP_A' END AS channel_zone, (SELECT MAX(t2.unit_price) FROM order_items t2 WHERE t2.product_id = s.product_id) AS max_order_item_unit_price FROM with_windows s ORDER BY max_order_item_unit_price DESC NULLS FIRST, product_id
